import{_ as r,l as i,o as e,c as l,v as t,p as s,x as n,d as T,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"NTT","description":"","frontmatter":{"title":"NTT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ntt.md","filePath":"cs/ntt.md","lastUpdated":1789023840000}'),h={name:"cs/ntt.md"};function c(m,a,_,u,f,N){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="ntt" tabindex="-1">NTT <a class="header-anchor" href="#ntt" aria-label="Permalink to &quot;NTT&quot;">​</a></h1><div class="epigraph"><p>模 $p$ 下若存在 $n$ 次单位根，DFT 的加减乘全部在整数进行：卷积精确，适合大整数与多项式取模。</p><footer>—— 据 CLRS 第 30、31 章；数论变换见 Nussbaumer 与数论教材整理</footer></div><p>上一课<a href="/cs/fft">FFT</a>在复数上 \\(O(n\\log n)\\)，浮点有误差。缺口是数论变换（NTT）：模素数 \\(p=k\\cdot n+1\\)，原根 \\(g\\)，\\(n\\) 次单位根 \\(\\omega=g^k\\)。不重写蝶形结构。后课多项式求逆仍用 NTT 乘。接<a href="/cs/finite-field-gf2n">有限域</a>的乘法直觉，不重写域公理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>要 \\(\\omega^n\\equiv 1\\pmod p\\)，且对真因子 \\(d\\mid n\\)，\\(\\omega^{n/d}\\not\\equiv 1\\)。则 Cooley–Tukey 原样，除 \\(n\\) 改模逆。常用 \\(p=998244353=119\\cdot 2^{23}+1\\) 等。多模 + CRT 拼回大整数（Schönhage–Strassen 一类精确乘的实践版）。</p><p>缺口是模意义单位根存在条件，不是新蝶形。</p><h3 id="不是任意模都能-ntt" tabindex="-1">不是任意模都能 NTT <a class="header-anchor" href="#不是任意模都能-ntt" aria-label="Permalink to &quot;不是任意模都能 NTT&quot;">​</a></h3><p>\\(n\\) 要整除 \\(p-1\\)。合数模没有域，不能随便当 NTT。长度不是 2 的幂可用 CRT 拼或其它原根阶。不要把 \\(10^9+7\\) 当总能做长度为 \\(2^{20}\\) 的 NTT——它不整除。</p><p><span class="marginnote">NTT 是 DFT 在环 \\(\\mathbb{Z}/p\\mathbb{Z}\\)。CLRS 30.8 讨论数论。后课求逆：牛顿迭代 + NTT 乘。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选 \\(p\\)、\\(n\\mid p-1\\)、原根。预处理 \\(\\omega\\) 幂。蝶形全模 \\(p\\)。逆变换乘 \\(n^{-1}\\)。多素数再 CRT。</p>',11)),(e(),s(p,null,{default:n(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22p%20%3D%20k%20n%20%2B%201%22%5D%20--%3E%20W%5B%22n%20%E6%AC%A1%E5%8D%95%E4%BD%8D%E6%A0%B9%22%5D%0A%20%20W%20--%3E%20NTT%5B%22%E6%A8%A1%20p%20%E8%9D%B6%E5%BD%A2%22%5D%0A%20%20NTT%20--%3E%20CONV%5B%22%E7%B2%BE%E7%A1%AE%E5%8D%B7%E7%A7%AF%20mod%20p%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[T(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>卷积长度与 \\(p\\) 同时约束。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>单位根的几何和在模 \\(p\\) 同样正交，故 IDFT 还原。与 FFT 比：无舍入，有模范围。与 Karatsuba：NTT 对很长多项式渐近更好，阈值仍实验。快速幂算 \\(\\omega\\) 与 \\(n^{-1}\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部常用模列表当作业。不写 p-adic、不写 Schönhage–Strassen 的完整复杂度陈述（可点名 \\(O(n\\log n\\log\\log n)\\) 级）。后课默认：精确多项式乘用 NTT。下一课多项式求逆与除法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>存在单位根的模上，DFT 全精确。</li><li>\\(n\\mid p-1\\)；常用 Fermat 素数型模。</li><li>大整数：多模 CRT。</li><li>出处：CLRS 第 30 章；NTT 为 DFT 的模算术形式。</li></ul>',7))])}const D=r(h,[["render",c]]);export{A as __pageData,D as default};
